      "section_id": "when-to-ship-when-to-iterate",
      "quote": "Ship when all evals meet their thresholds and no eval has regressed more than 2% from baseline."
    },
    {
      "doc_id": "ai-evals-m10",
      "section_id": "when-to-ship-when-to-iterate",
      "quote": "Iterate when the target eval improved, but other evals regressed."
    },
    {
      "doc_id": "ai-evals-m10",
      "section_id": "when-to-ship-when-to-iterate",
      "quote": "Revert when the change made things worse or had no measurable impact."
    }
  ],
